def load_plan(name):
    legacy.no_injected_options()
    assert name == 'probe-v1'
    folder = HERE / name
    plan = json.loads((folder / 'protocol.json').read_text())
    assert plan['name'] == name and plan['sources'] == sources(), 'Frozen diagnostic sources changed'
