    runtime, cp = selected_runtime()
    assert plan['sourceIdentity'] == runtime['sourceIdentity']
    assert plan['generatedMaterializerSha256'] == SOURCE_SHA and plan['classpathEntries'] == 130
    assert plan['fixture'] == FIXTURE and plan['order'] == ORDER and plan['masks'] == MASKS
    assert plan['warmup'] == WARMUP and plan['iterations'] == OBSERVED
    assert plan['expectedJvmCount'] == 4 and plan['expectedQueryCount'] == 52
    assert plan['queryLimitBytes'] == QUERY_LIMIT and plan['globalLimitBytes'] == GLOBAL_LIMIT
    assert plan['java'] == legacy.JAVA and plan['baseJvmArguments'] == legacy.JVM
    assert plan['consumption'] == 'full' and plan['transport'] == 'dense'
    assert plan['diagnosticOnly'] and not plan['performanceInference'] and not plan['acceptedTimingComparison']
    assert plan['resolverVariationAllowed'] and not plan['gcQueryAlignmentAvailable']
