def gc_evidence(path):
    text = path.read_text()
    lines = text.splitlines()
    return {'file': str(path), 'sha256': sha(path), 'bytes': path.stat().st_size,
        'lineCount': len(lines), 'g1Declared': 'Using G1' in text,
        'gcEventIds': sorted({int(value) for value in re.findall(r'GC\((\d+)\)', text)}),
        'referenceProcessingLineCount': sum(bool(re.search(r'\[gc,ref\s*\]', line)) for line in lines),
        'explicitSystemGcTextObserved': 'System.gc()' in text,
        'queryAlignmentAvailable': False, 'performanceInference': False}


def decomposition(owner, sample, reference, source_identity):
    targets = []
    for target, prior in zip(owner['targets'], reference['targets'], strict=True):
        assert all(target[key] == prior[key] for key in IDENTITY_FIELDS)
        delta = {key: value - prior[key] for key, value in target.items()
            if key not in IDENTITY_FIELDS and isinstance(value, int) and value != prior[key]}
        targets.append({'target': target['target'], 'name': target['name'], 'canonical': target['canonical'],
            'ordinaryPartition': {key: target[key] for key in ORDINARY},
            'terminalFactorMissPartition': {key: target[key] for key in FACTOR_MISSES},
            'factorHits': target['factorHit'], 'rememberCalls': target['rememberCall'],
            'pageAdmissionRefusals': target['pageRefused'], 'counterChangesFromSameArmReference': delta})
    total = lambda key: sum(target[key] for target in owner['targets'])
    return {'sourceIdentity': source_identity, 'generatedMaterializerSha256': SOURCE_SHA,
        'rawOwnerFile': owner['path'], 'rawOwnerSha256': owner['sha256'],
        'stage': sample['stage'], 'iteration': sample['iteration'],
        'resolverCalls': sample['counters']['lazyValueCalls'],
        'resolverDifferenceFromSameArmReference': sample['counters']['lazyValueCalls'] - reference['resolverCalls'],
        'ordinaryPartition': {key: total(key) for key in ORDINARY},
        'terminalFactorMissPartition': {key: total(key) for key in FACTOR_MISSES},
        'factorHits': total('factorHit'), 'pageAdmissionRefusals': total('pageRefused'),
        'coordinateAdmissionCounters': sample['counters']['coordinateAdmissions'],
        'targets': targets,
        'interpretation': 'Final factor misses are exclusive outcomes. Ordinary weak/witness branches may overlap '
            'with final factor misses or be recovered by factor hits; do not add their counts as extra resolvers.',
        'originalTimingEventCauseEstablished': False}


def validate_run(target, plan, entry):
    raw_file = target / 'samples.jsonl'
    records = [json.loads(line) for line in raw_file.read_text().splitlines()]
    metadata, queries = records[0], records[1:]
    checks = {'queryCount': len(queries) == WARMUP + OBSERVED}
    expected = {**FIXTURE['metadata'], 'source': plan['sourceIdentity'], 'arm': entry['harnessArm'],
        'jvmArguments': entry['jvmArguments'], 'consumption': 'full', 'nativeEvaluation': True,
        'directAdjacency': True, 'directAdjacencyMode': 'PREFER', 'valueOverlay': False, 'forceSync': False,
        'globalLedgerLimitBytes': GLOBAL_LIMIT, 'perQueryLedgerLimitBytes': QUERY_LIMIT,
        'indexes': 'spoc,ospc,psoc,posc', 'warmup': WARMUP, 'measurementsToRun': OBSERVED,
        'projectedNames': NAMES, 'javaVersion': '25.0.5+8-LTS', 'javaVendor': 'Eclipse Adoptium',
        'maxHeapBytes': GLOBAL_LIMIT}
    checks.update({'metadata:' + key: metadata.get(key) == value for key, value in expected.items()})
    properties = {arg[2:].split('=', 1)[0]: arg.split('=', 1)[1]
        for arg in entry['jvmArguments'] if arg.startswith('-Drdf4j.')}
    checks['metadata:systemProperties'] = metadata['systemProperties'] == properties
    setup = metadata['adjacencySetup']
    checks['adjacencySetup'] = setup['state'] == 'ACTIVE' and setup['currentRevisionReady']
    paths = sorted((target / 'page-records').glob('owner-*.jsonl'), key=lambda p: int(p.stem.split('-')[1]))
    owners = [legacy.owner_analysis(path) for path in paths]
    checks['oneOwnerPerQuery'] = len(owners) == len(queries)
    observations = []
    for i, sample in enumerate(queries):
        key = f'query{i}:'
        counters, adjacency = sample['counters'], sample['adjacency']
        checks[key + 'chronology'] = sample['iteration'] == i - WARMUP \
            and sample['stage'] == ('warmup' if i < WARMUP else 'measurement')
        checks[key + 'result'] = all(sample[field] for field in ('valid', 'complete', 'rowCountValid',
            'checksumValid', 'exactBagValid', 'partialMembershipValid')) \
            and sample['rows'] == FIXTURE['metadata']['expectedRows'] \
            and sample['checksum'] == FIXTURE['metadata']['expectedChecksum']
        checks[key + 'ledger'] = sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 \
            and sample['ledgerReleased'] and sample['ledgerPeakBytes'] <= QUERY_LIMIT
        checks[key + 'normalAUTO'] = sample['autoRequested'] and sample['auto'] \
            and bool(sample['successfulSelections']) and not any('forced' in r['mode'] for r in sample['successfulSelections'])
        checks[key + 'nativeIR'] = counters['semanticNativeCompiles'] == counters['irOpened'] == 1 \
            and counters['irRows'] == FIXTURE['metadata']['expectedRows']
        checks[key + 'coordinateOwner'] = counters['coordinateAdmissions']['opened'] == 1
        checks[key + 'compiledObservedQuery'] = i < WARMUP or counters['compiledBinds'] == 1 \
            and counters['interpretedBinds'] == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0
        checks[key + 'adjacency'] = adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE' \
            and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore'] \
            == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter'] == setup['currentDataRevision'] \
            and adjacency['lookupHits'] > 0
        if i >= len(owners):
            continue
        owner = owners[i]
        targets = owner['targets']
        checks[key + 'projectedNames'] = [t['name'] for t in targets] == NAMES
        checks[key + 'noAliases'] = all(t['target'] == t['canonical'] == j for j, t in enumerate(targets))
        checks[key + 'fullyBoundReads'] = sample['bindingReads'] == sample['rows'] * len(NAMES)
        eligible = all(checks[key + part] for part in ('projectedNames', 'noAliases', 'fullyBoundReads'))
        checks[key + 'findReconciliation'] = eligible and sum(t['find'] for t in targets) == sample['bindingReads']
        checks[key + 'hitResolverReconciliation'] = eligible \
            and sum(t['ordinaryHit'] + t['factorHit'] for t in targets) + counters['lazyValueCalls'] == sample['bindingReads']
        checks[key + 'rememberResolverReconciliation'] = eligible \
            and sum(t['rememberCall'] for t in targets) == counters['lazyValueCalls']
        checks[key + 'targetTerminalMissReconciliation'] = eligible \
            and all(t['rememberCall'] == sum(t[field] for field in FACTOR_MISSES) for t in targets)
        checks[key + 'ownerCounters'] = owner['valid'] and owner['header']['owner'] == i + 1
        checks[key + 'ownerQueryLimit'] = owner['header']['queryLimit'] == QUERY_LIMIT
        excluded = set(MASKS[entry['arm']].split(',')) - {''}
        checks[key + 'mask'] = all((t['publicationSkipped'] == t['publicationCall']
                and t['pageAdmitted'] == t['publicationWrite'] == t['finalPages'] == 0)
            if t['name'] in excluded else t['publicationSkipped'] == 0 for t in targets)
        owner['sample'] = {field: sample[field] for field in ('stage', 'iteration', 'rows', 'bindingReads',
            'checksum', 'ledgerBeforeBytes', 'ledgerPeakBytes', 'ledgerAfterBytes', 'counters', 'adjacency', 'successfulSelections')}
        if eligible:
            observations.append(decomposition(owner, sample, plan['references'][entry['arm']], plan['sourceIdentity']))
    audit_file = target / 'root-host-audit.json'
    audit = json.loads(audit_file.read_text())
    checks['rootAudit'] = audit['harnessReturned'] and audit['harnessFailureClass'] is None \
        and audit['hostedGenericTotal'] == 0 and audit['semanticNativeCompilesTotal'] == WARMUP + OBSERVED \
        and audit['harnessMain'] == FIXTURE['harnessMain'] and audit['readPhase'] == FIXTURE['rootReadPhase']
    gc = gc_evidence(target / 'gc.log')
    checks['gcLog'] = gc['lineCount'] > 0 and gc['g1Declared']
    checks['noExplicitGcText'] = not gc['explicitSystemGcTextObserved']
    analysis = {'format': 1, 'diagnosticOnly': True, 'valid': all(checks.values()), 'checks': checks,
        'arm': entry['arm'], 'runId': entry['runId'], 'mask': entry['mask'],
        'sourceIdentity': plan['sourceIdentity'], 'rawSamplesFile': str(raw_file), 'rawSamplesSha256': sha(raw_file),
        'metadata': metadata, 'owners': owners, 'observations': observations, 'rootAudit': audit,
        'rootAuditFile': str(audit_file), 'rootAuditSha256': sha(audit_file), 'gcLog': gc,
        'performanceInference': False, 'acceptedTimingComparison': False,
        'releaseCoverage': 'Page grants/releases are explicit. Ordinary/directory/memo are close-time claim snapshots; '
            'harness zero ledger endpoints are checked separately. These charges are not physical memory.'}
    write(target / 'analysis.json', analysis)
    assert analysis['valid'], 'Preserved diagnostic validation failure: ' + str(target)
    return analysis


def run(args):
    assert args.slot_granted, 'Java execution requires the coordinator exclusive slot'
    folder, plan, _ = load_plan(args.name)
    (folder / 'runs').mkdir(exist_ok=False)
    completed, errors = [], []
    try:
        for entry in plan['commands']:
            load_plan(args.name)
            target = Path(entry['directory'])
            target.mkdir()
            (target / 'page-records').mkdir()
            write(target / 'command.json', {**entry, 'startedEpochNs': time.time_ns(),
                'protocolSha256': sha(folder / 'protocol.json'), 'runtimeSha256': plan['runtimeSha256']})
            with (target / 'console.log').open('xb') as log:
                try:
                    process = subprocess.run(entry['argv'], cwd=ROOT, stdout=log, stderr=subprocess.STDOUT,
                        timeout=plan['timeoutSeconds'])
                except subprocess.TimeoutExpired:
                    write(target / 'process-result.json', {'exitCode': None, 'timedOut': True, 'finishedEpochNs': time.time_ns()})
                    raise
            write(target / 'process-result.json', {'exitCode': process.returncode, 'timedOut': False,
                'finishedEpochNs': time.time_ns()})
            assert process.returncode == 0, 'Preserved diagnostic process failure'
            analysis = validate_run(target, plan, entry)
            completed.append({'runId': entry['runId'], 'arm': entry['arm'], 'directory': str(target),
                'analysisFile': str(target / 'analysis.json'), 'analysisSha256': sha(target / 'analysis.json'),
                'queryCount': len(analysis['observations']), 'observations': analysis['observations']})
            print(json.dumps({'runId': entry['runId'], 'valid': True, 'queries': len(analysis['observations']),
                'resolverCalls': [q['resolverCalls'] for q in analysis['observations']],
                'ordinaryWeakBranches': sum(q['ordinaryPartition']['ordinaryWeakMiss'] for q in analysis['observations']),
                'terminalFactorWeakBranches': sum(q['terminalFactorMissPartition']['factorWeakMiss'] for q in analysis['observations']),
                'performanceInference': False}), flush=True)
        load_plan(args.name)
    except BaseException as failure:
        errors.append({'class': type(failure).__name__, 'message': str(failure), 'traceback': traceback.format_exc()})
        raise
    finally:
        count = sum(record['queryCount'] for record in completed)
        write(folder / 'summary.json', {'format': 1, 'diagnosticOnly': True,
            'complete': not errors and len(completed) == 4 and count == 52,
            'completedAndValidatedJvms': len(completed), 'validatedQueryCount': count,
            'protocolFile': str(folder / 'protocol.json'), 'protocolSha256': sha(folder / 'protocol.json'),
            'runtime': plan['runtime'], 'runtimeSha256': plan['runtimeSha256'], 'sourceIdentity': plan['sourceIdentity'],
            'runs': completed, 'errors': errors, 'performanceInference': False, 'acceptedTimingComparison': False,
            'originalTimingEventCauseEstablished': False,
            'interpretation': 'Instrumented branch observations only. No natural miss-rate, GC-performance, '
                'allocation or latency inference; original timing protocol remains stopped.', 'finishedEpochNs': time.time_ns()})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=('prepare', 'run'))
    parser.add_argument('--name', required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if args.action == 'prepare':
        prepare(args)
    else:
        run(args)


if __name__ == '__main__':
    main()
